import {suggestCategory} from './interface-rules.js';
import {validateTransition} from './record-operations.js';
import {createSimpleUI,mainDestination} from './workspace-simple.js';
import {enhanceWorkspace,enhanceChat,enhanceContent,modalFocusReturn} from './responsive.js';
import {regionCodes,currencyCodes,digits,parseMoney,formatMoney,dateInZone,validDate,totals,balance,spent,grouped,csv,fresh,migrateLegacy} from './core.js';
import {validateWorkspace,upgrade,cashKinds,asOfBalance,goalSavedAt} from './ledger.js';
import {createFeatures} from './workspace-features.js';
import {enrichDemo} from './demo-finance.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demo=new URLSearchParams(location.search).get('demo')==='1';
let replacingBackup=false;
let sessionEpoch=0,receiptChunkBytes=0,authProvider="chatgpt";
let state=fresh(),revision=0,user=null,active='USD',period='',page=decodeURIComponent(location.hash.slice(1))||'Overview',query='',type='all',collapsed=false,saving=false,chatOpen=false,chat=[],busy=false;
const nav=[['◫','Overview'],['▣','Accounts'],['◈','Cards'],['↙','Income & Salary'],['◇','Investments'],['◐','Net Worth'],['⇩','Import CSV'],['↶','Recovery'],['⇄','Transactions'],['▤','Budget Planner'],['▦','Financial Calendar'],['◎','Savings Goals'],['↗','Analytics'],['◉','Debt Manager'],['↻','Subscription Tracker'],['▧','Reports'],['✧','Mona'],['⚙','Settings']];
if(page==='Home')page='Overview';if(page==='Activity')page='Transactions';if(!nav.some(n=>n[1]===page)&&!['Wallet','More','Recurring & Bills'].includes(page))page='Overview';
const today=()=>dateInZone(state.profile?.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC');
const money=(n,c=active)=>formatMoney(n,c,state.profile?.locale||'en-US');
const date=s=>state.profile?.dateFormat==='iso'?s:new Intl.DateTimeFormat(state.profile?.locale||'en-US',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(s+'T12:00Z'));
const rows=(c=active)=>state.transactions.filter(t=>t.date.startsWith(period)&&(!c||t.currency===c));
const list=k=>state[k].filter(r=>r.currency===active);
const button=(s,a,cls='')=>`<button class="${cls}" data-action="${esc(a)}">${s}</button>`;
const empty=s=>`<p class="empty">${s}</p>`;
const id=()=>crypto.randomUUID();
let toastTimer;
function undoToast(message,undo){toast(message);const b=document.createElement('button');b.className='undo-action';b.textContent='Undo';b.onclick=async()=>{b.disabled=true;try{await undo()}catch(e){toast(e.message)}};$('#toast').append(b);clearTimeout(toastTimer);toastTimer=setTimeout(()=>{b.disabled=true;$('#toast').classList.remove('show')},12000);}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function lockWorkspace(reason='Your session ended. Sign in to restore your saved workspace.'){if(demo)return;sessionEpoch++;state=upgrade(fresh());user=null;revision=0;chat=[];chatOpen=false;$('#modal')?.close();$('#mona-root')?.remove();$('#app').innerHTML=`<main class="loading-screen"><h1>Workspace locked</h1><p>${esc(reason)}</p><a href="/signin-with-chatgpt?return_to=%2Fworkspace" target="_top">Sign in again</a><a href="/home.html">Return home</a></main>`}
async function api(path,method='GET',body){if(body instanceof FormData&&receiptChunkBytes&&path.startsWith('receipts?')){const file=body.get('receipt'),transaction=new URL('/api/'+path,location.origin).searchParams.get('transaction');if(!(file instanceof File))throw Error('Choose a receipt.');const upload=await api('receipt-upload','POST',{transaction,filename:file.name,size:file.size});try{const bytes=new Uint8Array(await file.arrayBuffer());for(let offset=0,n=0;offset<bytes.length;offset+=upload.chunkBytes,n++){const part=bytes.subarray(offset,offset+upload.chunkBytes);let binary='';for(let i=0;i<part.length;i+=32768)binary+=String.fromCharCode(...part.subarray(i,i+32768));await api('receipt-upload/'+upload.id,'PUT',{part:n,base64:btoa(binary)})}return await api('receipt-upload/'+upload.id,'POST',{})}catch(error){try{await api('receipt-upload/'+upload.id,'DELETE',{})}catch{}throw error}}const epoch=sessionEpoch;const r=await fetch('/api/'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body),credentials:'same-origin'});if(epoch!==sessionEpoch)throw Error('Your session changed. Sign in again.');let data;try{data=await r.json()}catch{throw Error('The server returned an unexpected response. Please retry.')}if(path==='session'){receiptChunkBytes=data.receiptChunkBytes||0;authProvider=data.authProvider||'chatgpt'}if(!r.ok){if(r.status===401){lockWorkspace();throw Error('Your session expired. Sign in again; your saved cloud data is preserved.');}throw Error(data.error||'Request failed.')}return data}
async function commit(change){if(saving)throw Error('A save is already in progress.');const next=upgrade(state);change(next);validateTransition(state,next,{replaceBackup:replacingBackup});validateWorkspace(next);saving=true;try{if(demo){sessionStorage.setItem('moneta-demo-v2',JSON.stringify(next));state=next}else{const r=await api('workspace','PUT',{workspace:next,revision,...(replacingBackup?{replaceBackup:true}:{})});state=r.workspace;revision=r.revision}render()}finally{saving=false}}
function download(name,text,mime='application/json'){const u=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function field(label,name,kind='text',value='',extra='',required=true){return `<label>${label}<input name="${name}" type="${kind}" value="${esc(value)}" ${extra} ${required?'required':''}></label>`}
function select(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`)}</select></label>`}
const currencyField=(c=state.currency)=>select('Currency','currency',currencyCodes.map(c=>[c,c]),c);
function amountField(label='Amount',name='amount',n='',currency=active,zero=false){return field(`${label} (${currency} · ${digits(currency)} decimal places)`,name,'text',n===''?'':String(n/10000),'inputmode="decimal" autocomplete="off"'+(zero?'':''))}
function modal(title,fields,submit){$('#modal').onclose=modalFocusReturn();$('#modal-title').textContent=title;$('#fields').innerHTML=fields;$('#form-error').textContent='';const save=$('#form button[type=submit]');save.textContent='Save changes';save.disabled=false;$('#form').onsubmit=async e=>{e.preventDefault();save.disabled=true;save.textContent='Saving…';$('#form-error').textContent='';try{await submit(Object.fromEntries(new FormData(e.target)));$('#modal').close();toast(demo?'Demo changes saved in this tab':'Saved to your account')}catch(e){$('#form-error').textContent=e.message}finally{save.disabled=false;save.textContent='Save changes'}};$('#close').onclick=()=>$('#modal').close();$('#modal').showModal();enhanceContent($('#modal'))}
function go(name,search='',m=period){name=({Home:'Overview',Activity:'Transactions'})[name]||name;page=name;query=search;period=m;history.pushState(null,'','#'+encodeURIComponent(page));window.dispatchEvent(new Event('moneta:navigate'));render();window.scrollTo({top:0,behavior:state.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function chart(){const months=Array.from({length:6},(_,i)=>{const d=new Date(period+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()-5+i);return [d.toISOString().slice(0,7),new Intl.DateTimeFormat(state.profile?.locale||'en-US',{month:'short',timeZone:'UTC'}).format(d)]});const data=months.map(([m,l])=>({...totals(state.transactions.filter(t=>t.currency===active&&t.date.startsWith(m))),label:l}));const max=Math.max(...data.flatMap(d=>[d.income,d.expense]),1);return `<div class="chart-legend"><span><i></i>Income</span><span><i class="coral"></i>Spending</span><span class="muted">${active} only · hover or focus for values</span></div><div class="chart" role="img" aria-label="Six month income and spending chart in ${active}">${data.map(d=>`<div class="chart-month"><div class="bars"><div class="bar" tabindex="0" style="height:${d.income/max*100}%" title="${esc(d.label)} income: ${money(d.income)}"><span>${d.income?money(d.income):''}</span></div><div class="bar coral" tabindex="0" style="height:${d.expense/max*100}%" title="${esc(d.label)} spending: ${money(d.expense)}"><span>${d.expense?money(d.expense):''}</span></div></div><small>${esc(d.label)}</small></div>`).join('')}</div>`}
function transactionTable(all=false){const ts=rows(null).filter(t=>(type==='all'||t.type===type)&&query.toLowerCase().split('|').some(q=>`${t.name} ${t.category}`.toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Account</th><th>Category</th><th class="right">Original amount</th><th></th></tr></thead><tbody>${ts.slice(0,all?1000:5).map(t=>`<tr><td><div class="transaction-name"><span class="mini-icon ${t.type}">${t.type==='income'?'↙':t.type==='transfer'?'⇄':'↗'}</span><div><strong>${esc(t.name)}</strong><small>${esc(date(t.date))}</small></div></div></td><td>${esc(state.accounts.find(a=>a.id===t.account)?.name)}</td><td><span class="status">${esc(t.category)}</span></td><td class="right ${t.type==='income'?'positive':''}"><strong>${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount,t.currency)}</strong></td><td>${button('⋯','edit:'+t.id)} ${button('↗','receipt:'+t.id)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching transactions. Add your first money move.</td></tr>'}</tbody></table></div>`}
function budgets(){return list('budgets').map(b=>{const n=spent(state.transactions,b.name,b.start,b.end,b.currency),pct=n/b.amount*100;return `<div class="budget-row"><div class="row"><strong>${esc(b.name)}</strong><span>${money(n)} <small>/ ${money(b.amount)}</small></span></div><div class="track" role="meter" aria-label="${esc(b.name)} budget used" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(pct))}"><div style="width:${Math.min(100,pct)}%;${pct>100?'background:#c45e4b':''}"></div></div><small>${money(Math.abs(b.amount-n))} ${n>b.amount?'over budget':'left'} · ${Math.round(pct)}% used · ${esc(date(b.start))}–${esc(date(b.end))}</small>${button('Remove','remove:budgets:'+b.id,'text-button')}</div>`}).join('')||empty('Give every dollar a direction.<br>Create a budget in '+active+'.')}
function goals(){return list('goals').map(g=>({...g,saved:goalSavedAt(g,period+'-'+new Date(Number(period.slice(0,4)),Number(period.slice(5)),0).getDate())})).map(g=>`<div class="goal"><div class="row"><strong>◎ &nbsp;${esc(g.name)}</strong><b class="positive">${Math.round(g.saved/g.amount*100)}%</b></div><small>${money(g.saved)} of ${money(g.amount)} · ${esc(date(g.date))}</small><div class="track segmented"><div style="width:${Math.min(100,g.saved/g.amount*100)}%"></div></div>${button('+ Contribute','contribute:'+g.id,'text-button')} ${button('History','history:'+g.id,'text-button')}</div>`).join('')||empty('A little today. A lot tomorrow.<br>Set a goal in '+active+'.')}
function bills(){return list('bills').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6).map(b=>`<div class="bill"><div class="row"><span class="date-tile">${b.date.slice(8)}<small>${esc(new Intl.DateTimeFormat(state.profile?.locale||'en-US',{month:'short',timeZone:'UTC'}).format(new Date(b.date+'T12:00Z')))}</small></span><span class="mini-icon">↻</span></div><strong>${esc(b.name)}</strong><b>${money(b.amount)}</b><small>${esc(b.cycle)} · ${esc(date(b.date))}</small>${button('Remove','remove:bills:'+b.id,'text-button')}</div>`).join('')||empty('No payments tracked in '+active+'.<br>Add your next bill to plan ahead.')}
function checklist(){const items=[['Add an account',state.accounts.length,'add-account'],['Record a transaction',state.transactions.length,'add-transaction'],['Create a budget',state.budgets.length,'add-budget'],['Set a savings goal',state.goals.length,'add-goal']];if(items.every(i=>i[1]))return '';return `<section class="setup-checklist"><div><span class="eyebrow">YOUR FIRST SMALL STEPS</span><h3>Make this space yours, ${esc(state.profile?.name||'one step at a time')}.</h3><p>${state.profile?.goal==='saving'?'Start with a goal, then build a plan around it.':'A few records are all it takes to see a clearer picture.'}</p></div><div>${items.map(([l,done,a])=>button(`${done?'✓':'○'} &nbsp;${l}`,a,done?'check-done':'')).join('')}</div></section>`}
function alerts(){const out=[];if(state.alerts?.budgets){const over=list('budgets').filter(b=>spent(state.transactions,b.name,b.start,b.end,b.currency)>b.amount);if(over.length)out.push(`${over.length} ${active} budget${over.length>1?'s are':' is'} over allocation.`)}if(state.alerts?.bills){const d=today();const end=new Date(d+'T12:00Z');end.setUTCDate(end.getUTCDate()+7);const n=state.bills.filter(b=>b.date>=d&&b.date<=end.toISOString().slice(0,10)).length;if(n)out.push(`${n} tracked payment${n>1?'s':''} due in the next 7 days.`)}return out.length?`<div class="alert-banner">◷ &nbsp;${esc(out.join(' '))} ${button('Manage alerts','nav:Settings','text-button')}</div>`:''}
function currencyTotals(){return ''}
function overview(){const t=totals(rows()),net=t.income-t.expense,allocated=list('budgets').reduce((n,b)=>n+b.amount,0),used=list('budgets').reduce((n,b)=>n+spent(state.transactions,b.name,b.start,b.end,b.currency),0);return `${features.overview()}${checklist()}${alerts()}${currencyTotals()}<section class="summary"><article class="balance-card"><div class="row"><span>Available cash</span><small>Selected ${active} accounts</small></div><h2>${money(features.cashTotal())}</h2><div class="balance-bottom">${state.accounts.filter(a=>a.currency===active&&cashKinds.includes(a.kind)).slice(0,2).map(a=>`<span>● ${esc(a.name)} <b>${money(asOfBalance(state,a.id,today()))}</b></span>`).join('')||'<span>Add an account to get started</span>'}</div></article>${[['↙','Income',t.income,'Recorded inflows for '+period],['↗','Spending',t.expense,'Recorded expenses for '+period],['◎','Net saved',net,t.income?`${(net/t.income*100).toFixed(1)}% savings rate`:'Add income to calculate savings rate']].map(([i,l,n,s])=>`<article class="metric"><span><i class="mini-icon">${i}</i> ${l}</span><h2>${money(n)}</h2><div class="flat-line"></div><small>${s}</small></article>`).join('')}</section><section class="dashboard-grid"><article class="card cash"><div class="card-head"><div><h3>Cash flow</h3><p>Monthly inflow, outflow and what stays yours</p></div><span class="pill">${active} · 6 months</span></div>${chart()}<div class="card-footer"><span>Monthly income <b>${money(t.income)}</b></span><span>Monthly spending <b>${money(t.expense)}</b></span><span>Net cash flow <b>${money(net)}</b></span></div></article><article class="card plan"><div class="card-head"><div><h3>Spending plan</h3><p>Make room for what matters</p></div>${button('+','add-budget','icon-button')}</div>${budgets()}<div class="row footer-line"><strong>${money(used)} / ${money(allocated)}</strong></div></article><article class="card savings"><div class="card-head"><div><h3>Savings goals</h3><p>Small steps. Clear progress.</p></div>${button('+','add-goal','icon-button')}</div>${goals()}<div class="row footer-line"><span>Actually allocated</span><strong>${money(list('goals').reduce((n,g)=>n+goalSavedAt(g,period+'-'+new Date(Number(period.slice(0,4)),Number(period.slice(5)),0).getDate()),0))}</strong></div></article><article class="card recent"><div class="card-head"><div><h3>Recent transactions</h3><p>Original currencies, across all your accounts</p></div>${button('View all ↗','nav:Transactions','text-button')}</div>${transactionTable()}</article><article class="card upcoming"><div class="card-head"><div><h3>Upcoming payments</h3><p>Manually tracked due dates in ${active}</p></div>${button('Manage bills','nav:Subscription Tracker','text-button')}</div><div class="bills">${bills()}</div></article></section>`}
function settings(){const p=state.profile;return `<article class="card settings"><h3>Your profile & regional preferences</h3><p><strong>${esc(p.name)}</strong> · ${esc(user?.email||'Demo account')}</p><p>${esc(p.country)} · ${esc(p.locale)} · ${esc(p.timeZone)} · Default ${state.currency}</p>${button('Edit profile & region','profile','primary')}<p>Default currency applies to new records only. It never converts or relabels existing accounts, transactions, goals or budgets.</p><h3>Appearance & alerts</h3><label>Appearance <select id="theme"><option value="light">Light</option><option value="dark" ${state.dark?'selected':''}>Dark</option></select></label><label class="checkbox"><input id="bill-alerts" type="checkbox" ${state.alerts?.bills?'checked':''}> Upcoming-bill alerts in the dashboard</label><label class="checkbox"><input id="budget-alerts" type="checkbox" ${state.alerts?.budgets?'checked':''}> Overspending alerts in the dashboard</label><p>No email, push or SMS reminders are configured.</p><h3>Your accounts</h3>${state.accounts.map(a=>`<div class="row budget-row"><strong>${esc(a.name)}</strong><span>${money(asOfBalance(state,a.id,today()),a.currency)}</span></div>`).join('')}${button('+ Add account','add-account')}<h3>Privacy & accessibility</h3><label class="checkbox"><input id="ai-access" type="checkbox" ${state.aiAccess?'checked':''}>Allow Mona calculated search to access my records</label><label class="checkbox"><input id="reduced-motion" type="checkbox" ${state.reducedMotion?'checked':''}>Reduce motion</label><p>No external AI provider is configured. Mona does not change records; links open forms for explicit review.</p><h3>Your data, your control</h3><p>${demo?'This is a sample workspace saved only in this browser tab.':'Your records and preferences are stored in your authenticated cloud workspace. Other devices restore them after sign-in. Save conflicts require a reload to prevent overwriting newer records.'}</p><div class="actions">${button('Download backup','backup')}${button('Restore backup','restore')}${!demo&&localStorage.getItem('moneta-v1')?button('Review legacy local import','legacy'):''}${button('Delete chat history','clear-chat')}${button(demo?'Reset demo':'Delete MONETA account data',demo?'reset-demo':'delete-account','danger')}</div><input type="file" id="restore-file" accept="application/json" hidden><h3>Something not quite right?</h3><p>Report a website issue or incorrect calculated answer. Feedback is stored for the site owner; avoid sharing private financial details.</p>${button('Send feedback','feedback')}<div class="actions"><a href="/information.html#privacy">Privacy notice</a><a href="/information.html#terms">Terms</a>${demo?'<a href="/workspace">Continue with ChatGPT</a>':'<a href="/signout-with-chatgpt?return_to=%2Fhome.html" target="_top">Sign out</a>'}</div></article>`}
function content(){const extended=features.content(page);if(extended!==null)return extended;if(page==='Overview')return overview();if(page==='Transactions')return `<article class="card"><div class="card-head"><div><h3>Your transactions</h3><p>All original currencies · ${period}</p></div><select id="type" aria-label="Transaction type">${['all','income','expense','transfer'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`)}</select></div><label class="search inline-search">⌕ <input id="table-search" aria-label="Filter transactions" placeholder="Search description or category" value="${esc(query)}"></label>${transactionTable(true)}</article>`;
if(page==='Budget Planner')return `<article class="card"><div class="card-head"><div><h3>A plan with purpose</h3><p>Custom category periods · ${active}</p></div>${button('+ Create budget','add-budget','primary')}</div>${budgets()}</article>`;
if(page==='Savings Goals')return `<article class="card"><div class="card-head"><div><h3>Your next milestones</h3><p>Allocations are separate from account transfers · ${active}</p></div>${button('+ Add goal','add-goal','primary')}</div>${goals()}</article>`;
if(page==='Subscription Tracker')return `<article class="card"><div class="card-head"><div><h3>Stay ahead of renewals</h3><p>Manually tracked dates. Entries do not automatically post transactions.</p></div>${button('+ Add payment','add-bill','primary')}</div><div class="bills">${bills()}</div></article>`;
if(page==='Analytics')return `<article class="card"><h3>The bigger picture · ${active}</h3>${chart()}<h3>Spending by category · ${period}</h3>${[...new Set(rows().filter(t=>['expense','refund'].includes(t.type)).flatMap(t=>t.splits?.map(x=>x.category)||[t.category]))].map(c=>`<div class="row budget-row"><strong>${esc(c)}</strong><b>${money(spent(rows(),c,period+'-01',period+'-31',active))}</b></div>`).join('')||empty('Add expenses to see your patterns.')}</article>`;
if(page==='Financial Calendar'){const days=new Date(Number(period.slice(0,4)),Number(period.slice(5)),0).getDate(),offset=new Date(period+'-01T12:00Z').getUTCDay();return `<article class="card"><h3>Your financial calendar</h3><p>Date-only records stay on their entered date. Today is ${esc(date(today()))} in ${esc(state.profile.timeZone)}.</p><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<b>${d}</b>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=period+'-'+String(i+1).padStart(2,'0');return `<div class="day ${d===today()?'today':''}"><strong>${i+1}</strong>${state.transactions.filter(t=>t.date===d).map(t=>`<button data-action="edit:${t.id}" class="event">${esc(t.name)} ${money(t.amount,t.currency)}</button>`).join('')}${state.bills.filter(b=>b.date===d).map(b=>`<span class="event bill-event">${esc(b.name)} ${money(b.amount,b.currency)}</span>`).join('')}</div>`}).join('')}</div></article>`}
if(page==='Debt Manager')return `<article class="card"><div class="card-head"><div><h3>A clearer path forward</h3><p>Estimates from entered balances, monthly interest and fixed payments · ${active}</p></div>${button('+ Add debt','add-debt','primary')}</div>${list('debts').map(d=>{let n=d.amount,m=0;while(n>0&&m<1200){n=Math.round(n*(1+d.rate/1200))-d.payment;m++}return `<div class="budget-row row"><div><h3>${esc(d.name)}</h3><p>${d.rate}% APR · ${money(d.payment)} / month</p></div><strong>${money(d.amount)}</strong><span>${m===1200?'Payment insufficient or >100 years':m+' months estimated'}</span>${button('Remove','remove:debts:'+d.id)}</div>`}).join('')||empty('Add a debt to understand your repayment path.')}</article>`;
if(page==='Reports'){const gs=grouped(rows(null));return `<article class="card"><h3>Your money, on your terms</h3><p>Original-currency reporting for ${period}. No exchange-rate service is configured, so currencies are never added together or converted.</p>${gs.map(t=>`<div class="report-total"><h3>${t.currency}</h3><span>Income <b>${money(t.income,t.currency)}</b></span><span>Expenses <b>${money(t.expense,t.currency)}</b></span><span>Net <b>${money(t.income-t.expense,t.currency)}</b></span></div>`).join('')||empty('No records for this period.')}<div class="actions">${button('↓ Export month CSV','export','primary')}${button('↓ Download full backup','backup')}</div><h3>How your numbers work</h3><p>Income and expenses sum recorded transactions in each currency and month. Transfers affect account balances but never income or expenses. Net saved = income − expenses. Savings rate = net saved ÷ income, or zero if income is zero. Category budgets include matching expenses within their exact dates. Goal contributions are allocated amounts, not additional account income.</p><h3>What-if spending simulator</h3><p>Selected reporting currency: ${active}. This estimate does not modify records.</p><label>Hypothetical expense reduction <input id="simulate" type="range" min="0" max="50" value="10"></label><p id="simulation">At 10% lower spending, net savings would be ${money(totals(rows()).income-Math.round(totals(rows()).expense*.9))}.</p></article>`}
if(page==='Mona')return `<article class="card insights"><span class="pill">✧ Mona · calculated search</span><h2>Find the answer.<br>See the source.</h2><p>Generative AI is unavailable: no provider is configured. ${demo?'Demo answers use sample data in this tab.':'Financial answers use validated server calculations on your authorized saved records.'} No data is sent to an AI provider. Mona is read-only.</p><div class="prompt-grid">${['How much did I spend on food this month?','Which budgets have I exceeded?','What bills are due this week?','How is my savings goal progressing?','Compare this month’s expenses with last month.'].map((s,i)=>button(esc(s),'prompt:'+i)).join('')}</div>${button('Open Mona','chat','primary')}</article>`;
return settings()}
function render(){if(!state.profile){onboarding();return}document.body.classList.add('simple-shell');document.documentElement.dataset.theme=state.dark?'dark':'light';document.documentElement.dataset.reducedMotion=state.reducedMotion?'true':'false';const n=simple.navigation(page),group=mainDestination(page);let body=simple.content(page);if(body===null)body=content();if(page==='Analytics')body+='<section class="card"><h3>Cash flow</h3>'+chart()+'</section>';$('#app').innerHTML=`<aside class="sidebar">${n.side}</aside><main><header><div><h1>${page==='Overview'?'Hi, '+esc(state.profile.name.split(' ')[0])+'.':esc(({'Transactions':'Transactions','Budget Planner':'Budget','Savings Goals':'Goals','Analytics':'Insights'})[page]||page)}</h1></div>${page==='Transactions'?'<div class="header-tools"><label class="search">⌕ <input id="search" placeholder="Search activity" aria-label="Search transactions" value="'+esc(query)+'"></label></div>':''}</header><div class="toolbar"><span class="workspace-status">${demo?'Sample workspace':'Saved workspace'}</span><div><select id="report-currency" aria-label="Reporting currency">${[...new Set([state.currency,...state.accounts.map(a=>a.currency),...state.transactions.map(t=>t.currency),active])].sort().map(c=>'<option '+(c===active?'selected':'')+'>'+c+'</option>').join('')}</select><input type="month" id="period" value="${period}" aria-label="Reporting month"></div></div>${demo?'<div class="demo-banner">Sample data only. <a href="/workspace">Open personal workspace</a></div>':''}<div class="${page==='Overview'?'home-content':'page-content'}">${body}</div><footer><span>${demo?'Demo in this tab':'Cloud save revision '+revision}</span><a href="/information.html#privacy">Privacy</a></footer></main>${n.bottom}`;bind();features.bind();simple.decorate($('#app'),page);renderChat();enhanceWorkspace()}
function renderChat(){const previousOpen=!!$('.mona-panel');const previousId=document.activeElement?.closest('#mona-root')?document.activeElement.id:null;let root=$('#mona-root');if(!root){root=document.createElement('div');root.id='mona-root';document.body.append(root)}root.innerHTML=`<button class="mona-launcher" data-action="chat" aria-label="${chatOpen?'Close':'Open'} Mona" aria-expanded="${chatOpen}">✧ <span>Mona</span></button>${chatOpen?`<section class="mona-panel" aria-label="Mona calculated search"><div class="mona-head"><div><strong>✧ Mona</strong><small>Calculated search · AI unavailable</small></div>${button('×','chat','icon-button')}</div><div class="mona-disclosure">${demo?'Sample data only.':'Your saved records only. No AI provider receives your data.'} Read-only answers.</div><div class="chat-log" aria-live="polite">${chat.length?chat.map(m=>`<article class="chat-message ${m.role}"><strong>${m.role==='user'?'You':'Mona'}</strong><p>${esc(m.text).replaceAll('\n','<br>')}</p>${m.links?.map((l,i)=>button(esc(l.label),`chatlink:${chat.indexOf(m)}:${i}`,'chat-link')).join('')||''}${m.matches?.map(t=>`<small>${esc(t.date)} · ${esc(t.name)} · ${esc(t.amount)}</small>`).join('')||''}${m.action?button('Review transaction form','add-transaction','chat-link'):''}</article>`).join(''):'<p class="empty">Try “What bills are due this week?” or “Show my savings goals.”</p>'}${busy?'<p class="empty">Checking your saved records…</p>':''}</div><form id="chat-form"><label class="sr-only" for="chat-question">Ask Mona</label><input id="chat-question" maxlength="500" placeholder="Ask about your money…" required autocomplete="off"><button class="primary" ${busy?'disabled':''}>Send ↗</button></form><div class="chat-controls">${button('Clear chat','clear-chat','text-button')}${button('Report an issue','feedback','text-button')}</div></section>`:''}`;if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#chat-question').value)};$('.chat-log')?.scrollTo(0,$('.chat-log').scrollHeight);enhanceChat(previousId,previousOpen)}
async function ask(q){if(busy)return;if(!state.aiAccess){toast('Mona record access is turned off in Settings.');return}chatOpen=true;chat.push({role:'user',text:q});busy=true;renderChat();try{let r;if(demo){const {monaAnswer}=await import('./mona-engine.js');r=monaAnswer(state,q)}else r=await api('mona','POST',{question:q});chat.push({role:'assistant',...r})}catch(e){chat.push({role:'assistant',text:e.message})}finally{busy=false;renderChat()}}
function regionFields(p={}){const names=new Intl.DisplayNames([p.locale||navigator.language||'en-US'],{type:'region'});const regions=regionCodes.map(c=>[c,names.of(c)]);regions.sort((a,b)=>a[1].localeCompare(b[1]));return `<div class="two-fields">${select('Country / region — please confirm','country',[['','Select your country / region'],...regions],p.country)}${currencyField(p.currency||state.currency)}</div>${field('Number and language locale','locale','text',p.locale||navigator.language||'en-US','placeholder="e.g. en-IN, de-DE, ja-JP"')}${field('Time zone','timeZone','text',p.timeZone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC','placeholder="e.g. Asia/Kolkata" list="time-zones"')}<datalist id="time-zones">${(Intl.supportedValuesOf?.('timeZone')||['UTC']).map(z=>`<option>${z}</option>`).join('')}</datalist>${select('Date display','dateFormat',[['locale','Regional date format'],['iso','YYYY-MM-DD']],p.dateFormat||'locale')}${select('Your primary goal','goal',[['spending','Control spending'],['budgets','Manage budgets'],['saving','Save toward a goal']],p.goal||'spending')}`}
function profileForm(p={},setup=false){return field('Your name','name','text',p.name||user?.name||'','maxlength="100" autocomplete="name"')+`<label>Sign-in email<input type="email" value="${esc(user?.email||'demo@example.invalid')}" readonly><small>Provided by your supported sign-in method.</small></label>`+regionFields({...p,currency:state.currency})+`<details class="optional-profile"><summary>Optional planning & contact details</summary><p>Planning amounts guide setup only. They do not create transactions or actual savings.</p>${field('Planned monthly income','plannedIncome','text',p.plannedIncome?p.plannedIncome/10000:'','inputmode="decimal"',false)}${field('Starting monthly budget','startingBudget','text',p.startingBudget?p.startingBudget/10000:'','inputmode="decimal"',false)}${field('Savings target','savingsTarget','text',p.savingsTarget?p.savingsTarget/10000:'','inputmode="decimal"',false)}<p>Mobile is optional and not used for alerts in this release. Leave it blank unless you want it stored as a contact preference.</p><div class="two-fields">${select('Calling code','dial',[['+1','+1 US / Canada'],['+44','+44 UK'],['+91','+91 India'],['+81','+81 Japan'],['+61','+61 Australia'],['+49','+49 Germany'],['custom','Other: enter full international number']],p.dial||'+1')}${field('Mobile number (optional)','phone','tel',p.phone||'','autocomplete="tel" maxlength="30"',false)}</div><label class="checkbox"><input type="checkbox" name="marketing" ${p.marketing?'checked':''}> Optional: save my interest in future product updates.</label><small>No marketing delivery service is configured. This consent is separate from account setup.</small></details>${setup?'<p class="form-note">Confirm your country and currency. Browser locale and time zone are suggestions only; travel will not change saved preferences.</p>':''}`}
function profileValue(v){const p={name:v.name.trim(),country:v.country,locale:v.locale.trim(),timeZone:v.timeZone.trim(),dateFormat:v.dateFormat,goal:v.goal,marketing:v.marketing==='on',dial:v.dial,phone:''};for(const k of ['plannedIncome','startingBudget','savingsTarget'])p[k]=v[k]?.trim()?parseMoney(v[k],v.currency,{zero:true}):null;if(v.phone?.trim()){let n=v.phone.replace(/[\s()-]/g,'');if(!n.startsWith('+'))n=(v.dial==='custom'?'':v.dial)+n;if(!/^\+[1-9]\d{6,14}$/.test(n))throw Error('Enter a valid international mobile number with country code (7–15 digits).');p.phone=n}return p}
function onboarding(){document.documentElement.dataset.theme='light';$('#app').innerHTML=`<main class="onboarding"><a class="brand" href="/home.html"><span class="brand-mark">M</span>MONETA</a><h1>Welcome to MONETA.</h1><p>Confirm your profile and region before recording money. No country or currency is inferred from your location.</p><details class="onboard-card profile-setup"><summary>Finish setup · 0/5</summary><span class="eyebrow">A SPACE THAT FITS YOU</span><h2>Your profile & region</h2><p>You’re signed in with ${authProvider==='clerk'?'your secure account':'ChatGPT'}. Confirm a few details to create your MONETA profile.</p><form id="onboarding-form">${profileForm({},true)}<p id="onboard-error" role="alert"></p><button class="primary" type="submit">Create my workspace ↗</button></form><p class="form-note">Review the draft <a href="/information.html#privacy">privacy notice</a> and <a href="/information.html#terms">terms</a>. Owner approval is required before commercial publication.</p></details></main>`;$('#onboarding-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='Creating your workspace…';try{const v=Object.fromEntries(new FormData(e.target));await commit(s=>{s.currency=v.currency;s.profile=profileValue(v)});active=state.currency;period=today().slice(0,7);render()}catch(e){$('#onboard-error').textContent=e.message;b.disabled=false;b.textContent='Create my workspace ↗'}};bindCountrySuggestion();enhanceWorkspace()}
function bindCountrySuggestion(){const c=$('[name=country]');if(c)c.onchange=()=>{const map={IN:'INR',US:'USD',GB:'GBP',JP:'JPY',AU:'AUD',CA:'CAD',DE:'EUR',FR:'EUR',NZ:'NZD',CH:'CHF',SG:'SGD',AE:'AED',KW:'KWD',BR:'BRL',ZA:'ZAR'};if(map[c.value])$('[name=currency]').value=map[c.value]}}
function transaction(tid,defaultType='expense',preset={}){const t=state.transactions.find(t=>t.id===tid)||{},accounts=state.accounts.filter(a=>a.kind!=='investment'&&(!a.archived||a.id===t.account||a.id===t.to));if(!tid&&preset.duplicate){if(!accounts.some(a=>a.currency===preset.currency))throw Error('Restore an account in '+preset.currency+' before duplicating this record.');Object.assign(t,preset);}if(t.group){modal('Edit linked repayment description',field('Description','name','text',t.name)+field('Notes','notes','text',t.notes||'','maxlength="2000"',false)+'<p>Amounts and dates are linked. To correct those, reverse the whole repayment in Recovery, then record the corrected repayment.</p>',v=>commit(s=>{Object.assign(s.transactions.find(x=>x.id===tid),{name:v.name,notes:v.notes})}));return;}if(t.investmentTrade){toast('Use investment history to review this linked trade.');return}if(t.type==='adjustment'){modal('Recorded reconciliation adjustment',`<p>${esc(t.name)} · ${money(t.amount,t.currency)} · ${esc(t.direction)}</p>${button('Move adjustment to Recovery','delete:'+t.id,'danger')}`,async()=>{});return}if(!accounts.length){toast('Add an account before recording a transaction.');addAccount();return}const ac=accounts.find(a=>a.id===(t.account||preset.account))||accounts.find(a=>a.currency===(t.currency||active))||accounts[0];modal(tid?'Edit transaction':'A new money move',select('Type','type',[['expense','Expense / card purchase / interest'],['income','Received income'],['transfer','Transfer / card or loan principal'],['refund','Expense refund']],t.type||defaultType)+field('Description','name','text',t.name||'','maxlength="120"')+select('Account / transfer source','account',accounts.map(a=>[a.id,`${a.name} (${a.currency})`]),ac.id)+amountField('Amount','amount',t.amount??'',ac.currency)+field('Date','date','date',t.date||today())+select('Transfer destination (same currency only)','to',[['','Choose a destination'],...accounts.filter(a=>a.currency===ac.currency&&a.id!==ac.id).map(a=>[a.id,`${a.name} (${a.currency})`])],t.to)+field('Category','category','text',t.category||'Uncategorized','maxlength="60"')+'<p id="category-suggestion" class="form-note" aria-live="polite">Category suggestions use merchant keywords. You can override them.</p>'+field('Notes (optional)','notes','text',t.notes||'','maxlength="2000"',false)+select('Linked debit card (optional)','card',[['','No linked debit card'],...state.cards.filter(d=>d.status==='active').map(d=>[d.id,d.name])],t.card||preset.card)+`<label>Split categories (optional; one Category:amount per line)<textarea name="splits" rows="3" placeholder="Food:60.00&#10;Household:40.00">${esc(t.splits?.map(x=>x.category+':'+x.amount/10000).join('\n')||'')}</textarea></label><p class="form-note">Transfers between different currencies need a verified conversion and are not supported.</p>`+(tid?button('Delete transaction','delete:'+tid,'danger'):''),async v=>{await commit(s=>{const a=s.accounts.find(a=>a.id===v.account);if(tid&&a.currency!==t.currency)throw Error('The original currency is preserved. Choose an account in '+t.currency+'.');const n={...v,id:tid||id(),currency:a.currency,amount:tid&&String(v.amount)===String(t.amount/10000)?t.amount:parseMoney(v.amount,a.currency),to:v.type==='transfer'?v.to:''};if(!v.card)delete n.card;if(v.splits.trim()){n.splits=v.splits.split(/\n/).filter(x=>x.trim()).map(line=>{const i=line.lastIndexOf(':');if(i<1)throw Error('Use Category:amount for each split.');return {category:line.slice(0,i).trim(),amount:parseMoney(line.slice(i+1).trim(),a.currency)}})}else delete n.splits;if(n.type==='transfer'&&(!s.accounts.some(a=>a.id===n.to&&a.currency===n.currency)||n.to===n.account))throw Error('Choose a different destination account in the same currency.');if(s.transactions.some(x=>x.id!==tid&&['name','date','amount','type','account','to','currency'].every(k=>x[k]===n[k])))throw Error('This transaction already exists.');if(tid)s.transactions=s.transactions.map(x=>x.id===tid?n:x);else s.transactions.push(n)})});let manualCategory=!!tid||!!t.category;const category=$('[name=category]'),merchant=$('[name=name]');merchant.addEventListener('input',()=>{if(!manualCategory){category.value=suggestCategory(merchant.value);$('#category-suggestion').textContent='Suggested: '+category.value+'. You can override this category.'}});category.addEventListener('input',()=>{manualCategory=true;$('#category-suggestion').textContent='Your category is preserved; merchant suggestions will not replace it.'});$('[name=account]').onchange=e=>{const a=accounts.find(a=>a.id===e.target.value);$('[name=amount]').parentElement.firstChild.textContent=`Amount (${a.currency} · ${digits(a.currency)} decimal places)`;$('[name=to]').innerHTML='<option value="">Choose a destination</option>'+accounts.filter(x=>x.currency===a.currency&&x.id!==a.id).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}}
function legacyAccountForm(){modal('A home for your money',field('Account name','name','text','','maxlength="120"')+currencyField()+field('Opening balance','opening','text','0','inputmode="decimal"')+'<p class="form-note">This original currency stays with the account. No currency conversion occurs.</p>',v=>commit(s=>s.accounts.push({id:id(),name:v.name,currency:v.currency,opening:parseMoney(v.opening,v.currency,{zero:true})})))}
function addAccount(){features.accountForm()}
function addBudget(){const end=new Date(Number(period.slice(0,4)),Number(period.slice(5)),0).getDate();modal('Create a spending plan',field('Category (match transaction category)','name','text','','maxlength="60"')+currencyField()+field('Allocated amount','amount','text',state.profile?.startingBudget?state.profile.startingBudget/10000:'','inputmode="decimal"')+field('Start date','start','date',period+'-01')+field('End date','end','date',period+'-'+end),v=>commit(s=>{if(v.end<v.start)throw Error('End date must follow start date.');if(s.budgets.some(b=>b.name===v.name&&b.currency===v.currency&&b.start<=v.end&&b.end>=v.start))throw Error('An overlapping category budget exists in this currency.');s.budgets.push({...v,id:id(),amount:parseMoney(v.amount,v.currency)})}))}
function addGoal(){modal('A goal worth saving for',field('Goal name','name','text','','maxlength="120"')+currencyField()+field('Target amount','amount','text',state.profile?.savingsTarget?state.profile.savingsTarget/10000:'','inputmode="decimal"')+field('Target date','date','date'),v=>commit(s=>s.goals.push({...v,id:id(),amount:parseMoney(v.amount,v.currency),saved:0,contributions:[]})))}
async function action(a){const [op,key,third]=a.split(':');try{
if(await simple.action(a))return;if(await features.action(a))return;if(op==='nav')go(key);else if(op==='collapse'){collapsed=!collapsed;render()}else if(op==='chat'){chatOpen=!chatOpen;renderChat();if(chatOpen)$('#chat-question')?.focus()}else if(op==='clear-chat'){chat=[];renderChat();toast('Chat cleared from this page')}else if(op==='prompt'){const qs=['How much did I spend on food this month?','Which budgets have I exceeded?','What bills are due this week?','How is my savings goal progressing?','Compare this month’s expenses with last month.'];ask(qs[Number(key)])}else if(op==='chatlink'){const l=chat[Number(key)].links[Number(third)];go(l.page,l.search||'',l.period?.match(/^\d{4}-\d{2}$/)?l.period:period)}else if(op==='add-account')addAccount();else if(op==='add-transaction')transaction();else if(op==='income')transaction(null,'income');else if(op==='edit')transaction(key);else if(op==='delete'){if(confirm('Permanently delete this transaction?')){await commit(s=>s.transactions=s.transactions.filter(t=>t.id!==key));$('#modal').close();toast('Transaction deleted')}}else if(op==='add-budget')addBudget();else if(op==='add-goal')addGoal();else if(op==='contribute'){const g=state.goals.find(g=>g.id===key);modal('Allocate a savings contribution',amountField('Amount actually allocated','amount','',g.currency)+'<p class="form-note">Record only money already allocated. This does not move money between accounts.</p>',v=>commit(s=>{const g=s.goals.find(g=>g.id===key),n=parseMoney(v.amount,g.currency);g.saved+=n;(g.contributions??=[]).push({date:today(),amount:n})}))}else if(op==='history'){const g=state.goals.find(g=>g.id===key);modal('Contribution history',`<p>${esc(g.name)} · ${g.currency}</p>${g.contributions?.map(c=>`<div class="row budget-row"><span>${esc(date(c.date))}</span><strong>${money(c.amount,g.currency)}</strong></div>`).join('')||empty('No detailed contributions recorded. Older allocated totals may predate contribution history.')}`,async()=>{});$('#form button[type=submit]').textContent='Close'}else if(op==='add-bill')modal('Track a payment',field('Payment name','name')+currencyField()+field('Amount','amount')+field('Next due date','date','date')+select('Frequency','cycle',[['Monthly','Monthly'],['Yearly','Yearly'],['One-time','One-time']]),v=>commit(s=>s.bills.push({...v,id:id(),amount:parseMoney(v.amount,v.currency)})));else if(op==='add-debt')modal('Track a debt',field('Debt name','name')+currencyField()+field('Current balance','amount')+field('Annual interest (%)','rate','number','0','min="0" max="100" step="0.01"')+field('Monthly payment','payment'),v=>commit(s=>s.debts.push({...v,id:id(),amount:parseMoney(v.amount,v.currency),rate:Number(v.rate),payment:parseMoney(v.payment,v.currency)})));else if(op==='remove'){if(confirm('Remove this tracked record?'))await commit(s=>s[key]=s[key].filter(r=>r.id!==third))}else if(op==='profile'){modal('Your profile & region',profileForm(state.profile),v=>commit(s=>{s.currency=v.currency;s.profile=profileValue(v)}));bindCountrySuggestion()}else if(op==='export')download('moneta-'+period+'.csv',csv(rows(null)),'text/csv;charset=utf-8');else if(op==='backup')download('moneta-backup-v2.json',JSON.stringify(state,null,2));else if(op==='restore')$('#restore-file').click();else if(op==='feedback'){if(demo){toast('Sign in to your personal workspace to submit feedback.');return}modal('Send feedback',`<label>What should we look at?<textarea name="message" required minlength="5" maxlength="1500" rows="5" placeholder="Describe an issue without private financial details."></textarea></label>`,v=>api('feedback','POST',{message:v.message}))}else if(op==='delete-account'){if(confirm('Delete all MONETA cloud records, profile and feedback? Export a backup first. This does not delete your external sign-in account.')){const deletion=await api('workspace','DELETE',{});state=fresh();revision=0;chat=[];chatOpen=false;$('#mona-root')?.remove();render();toast(deletion.receiptsPending?'Records removed. Receipt deletion is pending; reload and retry the pending receipt cleanup to finish.':'MONETA live records and receipt objects removed. Provider backup retention is separate.')}}else if(op==='reset-demo'){if(confirm('Reset this sample workspace?')){state=upgrade(demoState());sessionStorage.setItem('moneta-demo-v2',JSON.stringify(state));active=state.currency;render()}}else if(op==='legacy')legacyImport();
}catch(e){toast(e.message)}}
function legacyImport(){const raw=localStorage.getItem('moneta-v1');if(!raw){toast('No legacy records on this device.');return}let old;try{old=JSON.parse(raw)}catch{toast('Legacy data cannot be read. Download it from the original version if possible.');return}modal('Review your legacy local records',`<p>The previous app stored two-decimal amounts without per-record currency. Its saved display preference was <strong>${esc(old.currency)}</strong>, but that cannot prove the original currency. Confirm the currency used for these records. No browser region is used to guess it.</p>${select('Confirmed original currency','currency',[['','Choose the original currency'],...currencyCodes.map(c=>[c,c])],'')}<p>${old.transactions?.length||0} transactions · ${old.accounts?.length||0} accounts. Download an untouched backup before importing. Import appends records; it never replaces cloud data. Your original local data remains on this device. Legacy budget end dates such as November 31 are normalized to that month’s last valid date.</p>${button('Download untouched legacy backup','download-legacy')}`,async v=>{digits(v.currency);const migrated=validateWorkspace(migrateLegacy(old,v.currency));await commit(s=>{const prefix='legacy-'+id()+'-';if(s.legacyImported)throw Error('Legacy data has already been imported into this workspace.');for(const k of ['accounts','transactions','budgets','goals','bills','debts'])s[k].push(...migrated[k].map(r=>({...r,id:prefix+r.id,...(k==='transactions'?{account:prefix+r.account,to:r.to?prefix+r.to:''}:{})})));s.legacyImported=true})})}
function bind(){for(const [el,key] of [['ai-access','aiAccess'],['reduced-motion','reducedMotion']])if($('#'+el))$('#'+el).onchange=async e=>{try{await commit(s=>s[key]=e.target.checked)}catch(e){toast(e.message)}};if($('#period'))$('#period').onchange=e=>{if(e.target.value){period=e.target.value;render()}};if($('#report-currency'))$('#report-currency').onchange=e=>{active=e.target.value;render()};for(const n of ['search','table-search'])if($('#'+n))$('#'+n).oninput=e=>{const start=e.target.selectionStart,end=e.target.selectionEnd;query=e.target.value;render();const input=$('#'+n);input?.focus({preventScroll:true});if(Number.isInteger(start)&&Number.isInteger(end))input?.setSelectionRange(start,end)};if($('#type'))$('#type').onchange=e=>{type=e.target.value;render()};if($('#theme'))$('#theme').onchange=async e=>{try{await commit(s=>s.dark=e.target.value==='dark')}catch(e){toast(e.message)}};for(const [el,key] of [['bill-alerts','bills'],['budget-alerts','budgets']])if($('#'+el))$('#'+el).onchange=async e=>{try{await commit(s=>s.alerts={...s.alerts,[key]:e.target.checked})}catch(e){toast(e.message)}};if($('#simulate'))$('#simulate').oninput=e=>{const t=totals(rows());$('#simulation').textContent=`At ${e.target.value}% lower spending, net savings would be ${money(t.income-Math.round(t.expense*(1-e.target.value/100)))}. Estimate only; records stay unchanged.`};if($('#restore-file'))$('#restore-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1500000)throw Error('Backup exceeds the 1.5 MB limit.');const next=validateWorkspace(JSON.parse(await f.text()));if(next.demo&&!demo)throw Error('Demo backups cannot replace a personal workspace.');if(confirm('Replace current workspace with this validated backup? Export your current data first.')){replacingBackup=true;try{await commit(s=>{const generation=s.generation;Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next);s.generation=generation;s.demo=demo})}finally{replacingBackup=false}active=state.currency;render();toast('Backup restored.')}}catch(e){toast(e.message)}}}
