function demoState(){const s=fresh();s.demo=true;s.profile={name:'Alex',country:'US',locale:'en-US',timeZone:'America/New_York',dateFormat:'locale',goal:'saving'};s.accounts=[{id:'everyday',name:'Everyday',opening:55200000,currency:'USD'},{id:'reserve',name:'Goal reserve',opening:69600000,currency:'USD'}];const current=dateInZone(s.profile.timeZone).slice(0,7);for(let i=0;i<6;i++){const d=new Date(current+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()-5+i);const m=d.toISOString().slice(0,7);s.transactions.push({id:id(),date:m+'-01',name:'Monthly salary',type:'income',amount:[4500,4200,5100,4650,4550,4800][i]*10000,account:'everyday',category:'Salary',currency:'USD',to:''});['Housing','Groceries','Transport','Lifestyle','Other'].forEach((c,j)=>s.transactions.push({id:id(),date:m+'-'+String(j+2).padStart(2,'0'),name:['Housing payment','Grocery basket','Transit pass','Weekend & dining','Everyday essentials'][j],type:'expense',amount:([1300,620,280,510,530][j]-(5-i)*12)*10000,account:'everyday',category:c,currency:'USD',to:''}))}const end=new Date(Number(current.slice(0,4)),Number(current.slice(5)),0).getDate();s.budgets=['Housing','Groceries','Transport','Lifestyle','Other'].map((name,i)=>({id:id(),name,amount:[1400,700,350,600,550][i]*10000,start:current+'-01',end:current+'-'+end,currency:'USD'}));s.goals=[{id:'g1',name:'Emergency fund',amount:60000000,saved:42000000,date:'2027-06-01',currency:'USD',contributions:[]},{id:'g2',name:'Travel fund',amount:30000000,saved:18000000,date:'2027-08-01',currency:'USD',contributions:[]},{id:'g3',name:'Learning fund',amount:12000000,saved:9600000,date:'2027-03-01',currency:'USD',contributions:[]}];s.bills=[{id:'b1',name:'Housing payment',amount:13000000,date:current+'-02',cycle:'Monthly',currency:'USD'},{id:'b2',name:'Power bill',amount:960000,date:current+'-05',cycle:'Monthly',currency:'USD'},{id:'b3',name:'Membership',amount:240000,date:current+'-09',cycle:'Monthly',currency:'USD'}];return enrichDemo(s)}
async function start(){$('#app').innerHTML='<main class="loading-screen" role="status"><span class="brand-mark">M</span><h2>Bringing your money into focus…</h2><p>Loading your workspace.</p></main>';try{if(demo){try{state=validateWorkspace(JSON.parse(sessionStorage.getItem('moneta-demo-v2')))}catch{state=upgrade(demoState())}user={name:'Alex',email:'Demo account'}}else{const session=await api('session');if(!session.user){location.replace('/signin-with-chatgpt?return_to=%2Fworkspace');return}user=session.user;const r=await api('workspace');state=validateWorkspace(r.workspace);revision=r.revision;if(r.pendingReceiptPurge)setTimeout(()=>{if(confirm('Receipt deletion is pending. Retry removing only the pending receipt objects?'))api('receipt-purge','POST',{}).then(r=>toast(r.receiptsPending?'Receipt cleanup is still pending. Try again later.':'Pending receipt cleanup completed.')).catch(e=>toast(e.message))},100);}active=state.currency;period=today().slice(0,7);render()}catch(e){$('#app').innerHTML=`<main class="loading-screen"><h1>Your data is still yours.</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Retry</button><a href="/signin-with-chatgpt?return_to=%2Fworkspace" target="_top">Sign in again</a><a href="/home.html">Return home</a></main>`}}
